-- Silverpine Forest: creature abilities
-- Most of the zone's creatures had no AI and only melee'd, and the Ambermill and Vile Fin mobs ran classic rows copied from the
-- Dalaran mobs. Silverpine is the Cataclysm revamp, so their abilities are ported from the Cataclysm data, and from the classic data
-- where Cataclysm has none (Worg). Vile Fin Oracle's flag removal and Inconspicuous Bear's quest credit rows are kept.
-- Cataclysm's event flag 512 (while charmed) is a raid difficulty flag here and is dropped, and Ambermill Watcher's Renew on a
-- hurt friend uses SMART_EVENT_FRIENDLY_HEALTH, which LoA does not implement, so it only renews itself.
-- Archmage Ataeric keeps its scripted fight; Fenwick Thatros (C++) and the Midsummer creatures are not touched.
SET @ENTRIES := '1765,1766,1768,1778,1780,1781,1797,1888,1889,1908,1913,1914,3577,3578,12123,12431,12433,44367,44547,44549,44632,44906,44911,44954,44966,44987,45195,45219,45254,45255,45711,45750,45753,45855,45860,45861,45883,45896,45995,46037,46038,46039,46040,46048,46050,46058,46059,46061,46063,46064,46065,46086,46573,46574,46575,46981,46992,47003,47009,47012,47015,47023,51855';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
